contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount) public payable {
        require(receiver != address(0));
        require(amount > 0);
        require(address(this).balance >= amount);
        c.sendTo(receiver, amount); // fund c (we are the owner)
        uint before = address(c).balance;
        require(before >= amount);
        bool reverted;
        try c.sendTo(receiver, amount) { reverted = false; }
        catch { reverted = true; }
        uint after_ = address(c).balance;
        if (reverted) {
            assert(after_ == before);
        } else {
            assert(after_ == before - amount);
        }
    }
    receive() external payable {}
}

